                    if (MPLACA.Trim().Length > 0)
                        mOrd = 1; // no esta confirmada la cantidad de la orden pero ya se esta cargando el trailer
                    else
                        mOrd = 6; // no esta confirmada la cantidad de la orden
                else
                    if (mHrImp.ToString().Trim().Length > 0)
                {
                    if (TotSplitSur > 0 && MPLACA.Trim().Length == 0)
                        mOrd = 5;
                    else
                        if (MPLACA.Trim().Length > 0 && TotSplitSur == 0)
                        mOrd = 1;
                    else
                            if (MPLACA.Trim().Length > 0)
                        mOrd = 2;
                    else
                        mOrd = 4; // ya se imprimio la orden de venta
                }
                else
                        if (mHrImp.ToString().Trim().Length == 0 && MPLACA.Trim().Length == 0)
                {
                    if (TotSplitSur > 0)
                        mOrd = 2;
                    else
                        if (MPLACA.Trim().Length > 0 && TotSplitSur == 0 && TotSplit > 0)
                        mOrd = 1;
                    else
                            if (MPLACA.Trim().Length > 0 && TotSplitSur > 0 && TotSplit > TotSplitSur)
                        mOrd = 2;
                }
                else
                            if (MPLACA.Trim().Length > 0 && TotSplitSur == 0 && TotSplit > 0)
                    mOrd = 1;
                else
                                if (MPLACA.Trim().Length > 0 && TotSplitSur >= TotSplit)
                    mOrd = 2;
                else
                                    if (MPLACA.Trim().Length == 0 && TotSplitSur == 0 && TotSplit > 2)
                    mOrd = 2;
                DateTime horafiltro = DateTime.Now;
                DateTime hora1 = Convert.ToDateTime(Info["PDN_HORENT1"].ToString());
                DateTime horaINI = Convert.ToDateTime("07:00");
                if (hora1 < horaINI)
                {
                    horafiltro = Convert.ToDateTime(Info["PDN_HORENT1"].ToString()).AddDays(1);
                }
                else
                {
                    horafiltro = Convert.ToDateTime(Info["PDN_HORENT1"].ToString());
                }


                if (DT.Value.ToString("dd/MM/yyyy") != System.DateTime.Now.ToString("dd/MM/yyyy"))
                    Datos.Rows.Add(Folio, Convert.ToDateTime(Info["PDN_FECHA"]).ToString("dd/MM/yyyy"), Info["PDN_HORA"].ToString(), Info["CNTE_CLAVE"].ToString(), Info["PDN_TIPO"].ToString(),
                             Info["PROV_CLAVE"].ToString(), MANDEN, mhora, Tot.ToString("#,###"), TotS.ToString("#,###"), MPLACA, mHrImp, TotSplit.ToString("##0.00"), TotSplitSur, Info["PDN_OBSERVACION"].ToString(), MnomCli, MnomProv, Info["PDN_ESTATUS"].ToString(), 0, Info["PDN_HORENT1"].ToString(), horafiltro, Info["pdn_autorizado"].ToString());
                else
                    //if (Folio == "443752")
                    //    MessageBox.Show("Encontre");
                    if ((TotSplit > 0 && Info["PROV_CLAVE"].ToString().Trim() != "MRLUCKY" && Tot != TotS && Info["pdn_surtido"] != "S"))
                {
                    Datos.Rows.Add(Folio, Convert.ToDateTime(Info["PDN_FECHA"]).ToString("dd/MM/yyyy"), Info["PDN_HORA"].ToString(), Info["CNTE_CLAVE"].ToString(), Info["PDN_TIPO"].ToString(),
                             Info["PROV_CLAVE"].ToString(), MANDEN, mhora, Tot.ToString("#,###"), TotS.ToString("#,###"), MPLACA, mHrImp, TotSplit.ToString("##0.00"), TotSplitSur, Info["PDN_OBSERVACION"].ToString(), MnomCli, MnomProv, Info["PDN_ESTATUS"].ToString(), mOrd, Info["PDN_HORENT1"].ToString(), horafiltro, Info["pdn_autorizado"].ToString());
                    TotPed++;
                }

                //Info["PDN_FOLIO"].ToString()
            }
            //Datos.DefaultView.Sort = "orden, SPLITGEN desc";

            Datos.DefaultView.Sort = "HORAMAXSALfiltro, TRANSPORTE ASC";
            Datos = Datos.DefaultView.ToTable(true);
            DGPedidos.DataSource = Datos;
            decimal totgen = 0;
            int operacion = 0;
            foreach (DataRow row in Datos.Rows)
            {
                operacion = Convert.ToInt32(row["SplitGen"].ToString().Trim().Replace(".00", "")) - Convert.ToInt32(row["SplitSur"]);
                if (operacion > 0)
                {
                    totgen += Convert.ToDecimal(operacion);
                }
            }


            TxtSplit.Text = TotSS.ToString("###");
            TxtSplitD.Text = TotSG.ToString("###.0");
            TxtSplitG.Text = totgen.ToString("###.0");
            LblTotPed.Text = TotPed.ToString("#,##0");
            TxtSplitF.Text = (TotSG - TotSS).ToString("###.0");
            FormatoSalida();
            thisConnecion.Close();
            if (DT.Value.ToString("dd/MM/yyyy") == System.DateTime.Now.ToString("dd/MM/yyyy"))
            {
                LLenaInventario();
                Pedidosdeldia(DT.Value.ToString("dd/MM/yyyy"));
                thisConnecion.Open();
                Cadena = "SELECT CONSE,FECHA,TURNO,RESPONSABLE,TEMP,HORAREGVIG,HORAENT,HORASAL,TIEMPOTOT,CHOFER,DESTINO,HORAINI,HORAFIN,TiempoCar,ANDEN,TRANSPORTE,NO_TRAILER,LARGO,SURTIBLE,PLACA,RADIO,OBSTRANS,OBSCAUSA,OBSFALTA,PDN_FOLIO FROM TB_MSTR_TRAILER WHERE FECHA = '" + DT.Value.ToString("dd/MM/yyyy") + "' AND CONSE > 0 ORDER BY FECHA,CONSE ";
                cmd = new SqlCommand(Cadena, thisConnecion);
                Info = cmd.ExecuteReader();
                while (Info.Read())
                {
                    string HF = (Info["horafin"].ToString().Trim().Length > 5) ? Info["horafin"].ToString().Substring(11, 13) : "";
                    string VarSur = (HF.Trim() != "") ? "C" : "";
                    if (VarSur == "C" || VarSur == "T")
                        ACTSURTIDO(Info["no_trailer"].ToString());
                }
                thisConnecion.Close();
            }

            LblMsjEmbPen.Visible = false;
            //thisConnecionDBGAB.Close();
        }

