                    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.Red;
                if (DGPedidos.Rows[i].Cells["ORDEN"].Value.ToString().Trim() == "2")
                    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.LightGreen;
                if (DGPedidos.Rows[i].Cells["ORDEN"].Value.ToString().Trim() == "4")
                    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.Gray;
