                    DGPedidos.Rows[i].DefaultCellStyle.Font = new Font("Arial", 8, FontStyle.Italic);
                if (DGPedidos.Rows[i].Cells["ORDEN"].Value.ToString().Trim() == "1")
                    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.Yellow;
                if (DGPedidos.Rows[i].Cells["ORDEN"].Value.ToString().Trim() == "5")
                    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.Orange;
                if (DGPedidos.Rows[i].Cells["ORDEN"].Value.ToString().Trim() == "3")
                    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.SkyBlue;
                if (DGPedidos.Rows[i].Cells["STATUS"].Value.ToString().Trim() == "")
                    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.Red;
                if (DGPedidos.Rows[i].Cells["STS"].Value.ToString().Trim() == "P")
