        public decimal Fn_Tot_Split(string var_folio, string var_tipo)
        {
            decimal Tot = 0;
            string Cadena = "";
            Cadena = "SELECT A.PROD_CLAVE,A.PDN_NUM_UNIDADES,B.PROD_NUM_TARIMAS FROM TB_DET_PEDIDOS A, TB_CAT_PRODUCTO B WHERE A.PDN_FOLIO = '" + var_folio + "' AND A.PDN_TIPO = '" + var_tipo + "' AND A.PROD_CLAVE = B.PROD_CLAVE";
            DataSet ds = new DataSet();
            SqlDataAdapter da = new SqlDataAdapter(Cadena, thisConnecion);
            SqlCommand cmd;
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion;
            SqlDataReader DetPed;
            DetPed = cmd.ExecuteReader();
            while (DetPed.Read())
            {
                decimal T = 0, T1 = 0;
                if (Convert.ToDecimal(DetPed["PROD_NUM_TARIMAS"]) != 0)
                {
                    T = Math.Floor(Convert.ToDecimal(DetPed["PDN_NUM_UNIDADES"]) / Convert.ToDecimal(DetPed["PROD_NUM_TARIMAS"]));
                    T1 = (Convert.ToDecimal(DetPed["PDN_NUM_UNIDADES"]) / Convert.ToDecimal(DetPed["PROD_NUM_TARIMAS"]));
                    Tot = Tot + (T1 - T);
                }
            }
            //if (var_tipo == "NAL")
            //    foreach (DataRow row1 in Det_PedNal.Select("PDN_FOLIO = '" + var_folio + "' AND PDN_TIPO = '" + var_tipo + "'"))
            //        Tot = Tot + Convert.ToInt32(row1["PDN_NUM_UNIDADES"]);
            //else
            //    foreach (DataRow row1 in Det_PedExp.Select("PDN_FOLIO = '" + var_folio + "' AND PDN_TIPO = '" + var_tipo + "'"))
            //        Tot = Tot + Convert.ToInt32(row1["PDN_NUM_UNIDADES"]);
            return Tot;
        }

