        public string Fn_Tiempo3(string TI, string TF)
        {
            string cad = "";
            decimal T1 = (Convert.ToInt32(TI.Substring(0, 2)) * 60) + Convert.ToInt32(TI.Substring(3, 2));   //(VAL(SUBSTR(TB_MSTR_EMBARQUE.HORA_INI,1,2))*60)+VAL(SUBSTR(TB_MSTR_EMBARQUE.HORA_INI,4,2))
            decimal T2 = (Convert.ToInt32(TF.Substring(0, 2)) * 60) + Convert.ToInt32(TF.Substring(3, 2));   //(VAL(SUBSTR(TB_MSTR_EMBARQUE.HORA_INI,1,2))*60)+VAL(SUBSTR(TB_MSTR_EMBARQUE.HORA_INI,4,2))
            decimal T = 0;
            if (T2 < T1)
                T = (1440 - T1) + (T2);
            else
                T = T2 - T1;
            decimal H = Math.Floor(T / 60);
            decimal M = 0;
            if (T > 60)
                M = Math.Round(((T / 60) - H) * 60, 0);
            else
                M = T;
            cad = H.ToString().Trim().PadLeft(2, '0') + ':' + M.ToString().Trim().PadLeft(2, '0'); // + " HRS";
            return cad;
        }

