        public string DetTarimas(string MFOL)
        {
            thisConnecion.Open(); //DBGAB
            string cad = " SELECT a.seccion, a.id_tarima, a.Emb_Folio, b.nom_tarima " +
                          " FROM Tb_Det_Embarque A, Tb_Cat_Tarima B " +
                          " WHERE A.Id_Tarima = B.Id_Tarima and a.emb_FOLIO = '" + MFOL + "'" +
                          " GROUP BY a.Id_tarima, a.seccion, b.Nom_Tarima,a.Emb_Folio ";
            SqlCommand cmd;
            cmd = new SqlCommand(cad);
            cmd.Connection = thisConnecion; //DBGAB
            SqlDataReader Info;
            Info = cmd.ExecuteReader();
            string a = "", datos = "", nomtar = "";
            int tot = 0, i = 0;

            while (Info.Read())
            {
                if (i == 0)
                {
                    a = Info["id_tarima"].ToString();
                    nomtar = Info["nom_tarima"].ToString();
                }
                if (a != Info["id_tarima"].ToString())
                {
                    datos = datos + nomtar.Trim() + " Cant: " + tot.ToString().Trim() + ", ";
                    a = Info["id_tarima"].ToString();
                    nomtar = Info["nom_tarima"].ToString();
                    tot = 0;
                }
                tot++;
                i++;
            }
            datos = datos + nomtar.Trim() + " Cant: " + tot.ToString().Trim() + ",";
            thisConnecion.Close(); //DBGAB
            return datos;

        }

