        private void ExpExcel_Click(object sender, EventArgs e)
        {
            if (DGEmbCap.Rows.Count == 0)
                return;
            Microsoft.Office.Interop.Excel.Application excel = new Microsoft.Office.Interop.Excel.Application();
            excel.Application.Workbooks.Add(Type.Missing);
            excel.Cells[1, 4] = "COMERCIALIZADORA GAB SA DE C.V.";
            excel.Cells[2, 4] = "EMBARQUES";
            excel.Cells[3, 4] = "Control de Hora de Carga de Tráiler";
            excel.Cells[4, 4] = "FECHA INICIAL:" + DtFI.Value.ToString("dd/MM/yyyy");
            excel.Cells[4, 6] = "FECHA FINAL:" + DtFF.Value.ToString("dd/MM/yyyy");
            excel.Cells[6, 1] = "Número"; excel.Cells[6, 2] = "Fecha"; excel.Cells[6, 3] = "Turno"; excel.Cells[6, 4] = "Supervisor de Carga"; excel.Cells[6, 5] = "Transporte"; excel.Cells[6, 6] = "Chofer"; excel.Cells[6, 7] = "Destino"; excel.Cells[6, 8] = "Anden"; excel.Cells[6, 9] = "Hora Inicio Carga";
            excel.Cells[6, 10] = "Hora Fin de Carga"; excel.Cells[6, 11] = "Observaciones"; excel.Cells[6, 12] = "PLACA";

            int rowIndex = 6;
            foreach (DataRow row in Embarques.Rows)
            {
                excel.Cells[rowIndex + 1, 1] = (rowIndex - 5).ToString();
                excel.Cells[rowIndex + 1, 2] = Convert.ToDateTime(row["Fecha"]).ToString("MM/dd/yyyy");
                excel.Cells[rowIndex + 1, 3] = row["Turno"].ToString();
                excel.Cells[rowIndex + 1, 4] = row["Responsable"].ToString().Trim();
                excel.Cells[rowIndex + 1, 5] = row["Transporte"].ToString().Trim();
                excel.Cells[rowIndex + 1, 6] = row["Chofer"].ToString().Trim();
                excel.Cells[rowIndex + 1, 7] = row["DEstino"].ToString().Trim();
                excel.Cells[rowIndex + 1, 8] = row["Anden"].ToString();
                string A = row["HoraIni"].ToString().Substring(11, 13);
                A = A.Replace("a.m.", "AM");
                A = A.Replace("p.m.", "PM");
                excel.Cells[rowIndex + 1, 9] = A;  //row["HoraIni"].ToString().Substring(11,13);
                A = row["HoraFin"].ToString().Substring(11, 13);
                A = A.Replace("a.m.", "AM");
                A = A.Replace("p.m.", "PM");
                excel.Cells[rowIndex + 1, 10] = A; //row["HoraFin"].ToString().Substring(11,13);
                excel.Cells[rowIndex + 1, 11] = "";
                excel.Cells[rowIndex + 1, 12] = row["NO_Trailer"].ToString().Trim();
                rowIndex++;
            }
            //excel.Columns.AutoFit();
            //LblMsj.Visible = false;
            //excel.Visible = true;
            excel.Columns.AutoFit();
            excel.Rows.AutoFit();
            excel.Visible = true;
        }

