        private void LlenaDGVPlacasLNP()
        {
            DGVPlacasLNP.DataSource = GetListaNegra();
        }
        private DataTable GetListaNegra(bool soloActivos = true)
        {
            DataTable dt = new DataTable();
            try
            {
                thisConnecion.Open();
                using (SqlCommand cmd = new SqlCommand("SELECT * FROM vw_lista_negra_actual", thisConnecion))
                {
                    cmd.CommandType = CommandType.Text;
                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    da.Fill(dt);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error al consultar la lista negra: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            finally
            {
                if (thisConnecion.State == ConnectionState.Open)
                    thisConnecion.Close();
            }
            return dt;
        }

        private void InsertarListaNegra(string placa, string motivo)
        {
            try
            {
                if (thisConnecion.State != ConnectionState.Open)
                    thisConnecion.Open();

                using (SqlCommand cmd = new SqlCommand("dbo.sp_InsertarListaNegraEMB", thisConnecion))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.AddWithValue("@Placa", placa.Trim());
                    cmd.Parameters.AddWithValue("@Motivo", motivo.Trim());

                    // Ejecuta y obtiene el nuevo ID devuelto por SCOPE_IDENTITY()
                    int nuevoId = (int)cmd.ExecuteScalar();

                    MessageBox.Show("Registro insertado en la lista negra con ID: " + nuevoId, "Éxito", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            }
            catch (SqlException sqlEx)
            {
                MessageBox.Show("Error SQL al insertar en la lista negra: " + sqlEx.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error general: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            finally
            {
                if (thisConnecion.State == ConnectionState.Open)
                    thisConnecion.Close();
            }
        }
