        private void btnRetirarLNP_Click(object sender, EventArgs e)
        {
            if (DGVPlacasLNP.CurrentRow == null)
            {
                MessageBox.Show("Seleccione una placa de la lista negra para retirarla.", "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            esAlta = false; // Modo baja
            modoRetirar = true; // Nuevo flag para controlar el modo retirar

            txtBoxPlacaLNP.Text = DGVPlacasLNP.CurrentRow.Cells["Placa"].Value.ToString().Trim();
            txtBoxPlacaLNP.ReadOnly = true; // No se puede cambiar

            txtBoxMotivoLNP.Clear();
