        private void InsertarAltaListaNegra(string placa, string motivo)
        {
            try
            {
                thisConnecion.Open();
                using (SqlCommand cmd = new SqlCommand("dbo.sp_AltaListaNegra", thisConnecion))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.AddWithValue("@Placa", placa);
                    cmd.Parameters.AddWithValue("@Motivo", motivo);
                    cmd.ExecuteNonQuery();
                    MessageBox.Show("Placa agregada a la lista negra.", "Éxito", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error al agregar placa: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            finally
            {
                if (thisConnecion.State == ConnectionState.Open)
                    thisConnecion.Close();
            }
        }
        private void InsertarBajaListaNegra(string placa, string motivo)
        {
            try
            {
                thisConnecion.Open();
                using (SqlCommand cmd = new SqlCommand("dbo.sp_BajaListaNegra", thisConnecion))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.AddWithValue("@Placa", placa);
                    cmd.Parameters.AddWithValue("@Motivo", motivo);
                    cmd.ExecuteNonQuery();
                    MessageBox.Show("Placa retirada de la lista negra.", "Éxito", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error al retirar placa: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            finally
            {
                if (thisConnecion.State == ConnectionState.Open)
                    thisConnecion.Close();
            }
        }
        private void btnGuardar_Click(object sender, EventArgs e)
        {
            string placa = txtBoxPlacaLNP.Text.Trim();
            string motivo = txtBoxMotivoLNP.Text.Trim();

            if (string.IsNullOrEmpty(placa))
            {
                MessageBox.Show("Ingrese la placa.", "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }
            if (string.IsNullOrEmpty(motivo))
            {
                MessageBox.Show("Ingrese el motivo.", "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (esAlta)
                InsertarAltaListaNegra(placa, motivo);
            else
                InsertarBajaListaNegra(placa, motivo);

            // Limpia controles
            txtBoxPlacaLNP.Clear();
            txtBoxMotivoLNP.Clear();
            txtBoxPlacaLNP.ReadOnly = true;
            txtBoxMotivoLNP.ReadOnly = true;

            esAlta = false;
            modoRetirar = false;

            btnGuardar.Enabled = false;
            btnAgregarLNP.Enabled = true;
            btnRetirarLNP.Enabled = true;
            btnCancelar.Visible = false;

            // Refresca el grid
            LlenaDGVPlacasLNP();
        }
        private void DGVPlacasLNP_SelectionChanged(object sender, EventArgs e)
        {
            if (DGVPlacasLNP.CurrentRow == null)
                return;

            DataGridViewRow fila = DGVPlacasLNP.CurrentRow;

            // Solo actualizar los TextBox si NO estamos en modo Alta ni en modo Retirar
            if (!esAlta && !modoRetirar)
            {
                txtBoxPlacaLNP.Text = fila.Cells["Placa"].Value.ToString().Trim();
                txtBoxMotivoLNP.Text = fila.Cells["Motivo"].Value.ToString().Trim();

                txtBoxPlacaLNP.ReadOnly = true;
                txtBoxMotivoLNP.ReadOnly = true;
            }
        }

