        public string obtenerhorariosalida(string pedido)
        {
            string horario = "";
            string BD = "tb_mstr_pedidos_NAL";
            if (Convert.ToInt32(pedido) < 400000)
            {
                BD = "tb_mstr_pedidos_EXP";
            }
            String Cadena = "SELECT pdn_horent1 FROM " + BD + " WHERE PDN_FOLIO = '" + Convert.ToInt32(pedido) + "'";
            SqlCommand cmd;
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion;
            SqlDataReader Info;
            Info = cmd.ExecuteReader();
            while (Info.Read())
            {
                horario = Info["pdn_horent1"].ToString();
            }

            return horario;
        }


        private void TotEmbDia(string mfec)
        {
            int Tot = 0;
            string Cadena = "SELECT PROV_CLAVE,placacaja, pdn_tipo " +
                            " FROM tb_mstr_pedidos_nal " +
                            " WHERE pdn_fecha >= '" + mfec + "' AND pdn_fecha <= '" + mfec + "' AND PDN_ESTATUS != 'C' AND Prov_clave != 'MRLUCKY' AND (placacaja != '' or PROV_CLAVE != 'PC')" +
                            " UNION " +
                            " SELECT PROV_CLAVE,placacaja, pdn_tipo " +
                            " FROM tb_mstr_pedidos_exp " +
                            " WHERE pdn_fecha >= '" + mfec + "' AND pdn_fecha <= '" + mfec + "' AND PDN_ESTATUS != 'C' AND Prov_clave != 'MRLUCKY' AND (placacaja != '' or PROV_CLAVE != 'PC')" +
                            " GROUP BY PROV_CLAVE,placacaja, pdn_tipo  ";
            DataSet ds = new DataSet();
            SqlDataAdapter da = new SqlDataAdapter(Cadena, thisConnecion);
            da.Fill(ds, "TEmb");
            DataTable TotEmb = ds.Tables["TEmb"];
            Tot = TotEmb.Rows.Count;
            Cadena = "SELECT PROV_CLAVE,' ' AS PLACACAJA, EMB_tipo AS PDN_TIPO " +
                     " FROM tb_mstr_ORDENES_EMB " +
                     " WHERE EMB_fecha >= '" + mfec + "' AND EMB_fecha <= '" + mfec + "' ";

            ds = new DataSet();
            da = new SqlDataAdapter(Cadena, thisConnecion);
            da.Fill(ds, "TEmb1");
            DataTable TotEmb1 = ds.Tables["TEmb1"];
            Tot = Tot + TotEmb1.Rows.Count;
            LblTotEmb.Text = Tot.ToString();
        }

        private void LLenaBas(string Tipo)
        {
            string pesoTotalEstimado = "";
            DGBasc.Rows.Clear();
            string mfec = DTBasc.Value.ToString("dd/MM/yyyy");
            string mfecF = DTBascF.Value.ToString("dd/MM/yyyy");
            Utilerias.Class1.registrar_movimiento(DateTime.Now, Environment.MachineName, Utilerias.Class1.Usu_login, "G", "7.1", "REPORTEREVISIONBASCULA", "REPORTE GENERADO DE LA FECHA: " + mfec + " A LA FECHA " + mfecF, "SIPGAB");
            thisConnecion.Open();
            string Cadena = "";
            if (Tipo == "TRAILERS") // trailer
                                    //Cadena = "SELECT CONSE,FECHA,TURNO,RESPONSABLE,HORAREGVIG,HORAENT,HORASAL,CHOFER,DESTINO,ANDEN,TRANSPORTE,NO_TRAILER,PLACA,PESOBASCULA,PDN_FOLIO FROM TB_MSTR_TRAILER WHERE FECHA BETWEEN '" + mfec + "' AND '" + mfecF + "' AND CONSE > 0 ORDER BY FECHA,CONSE ";
                Cadena = "SELECT A.CONSE, A.FECHA, A.TURNO, B.PDN_TIPO, A.RESPONSABLE, A.HORAREGVIG, A.HORAENT, A.HORASAL, A.CHOFER, A.DESTINO, A.ANDEN, A.TRANSPORTE, A.NO_TRAILER, A.PLACA, A.PESOBASCULA, A.PESO, A.PDN_FOLIO FROM TB_MSTR_TRAILER A JOIN tb_mstr_pedidos_exp B ON A.pdn_folio = B.pdn_folio WHERE A.fecha BETWEEN '" + mfec + "' AND '" + mfecF + "' AND B.pdn_fecha BETWEEN '" + mfec + "' AND '" + mfecF + "' AND A.conse > 0 UNION SELECT A.CONSE, A.FECHA, A.TURNO, B.PDN_TIPO, A.RESPONSABLE, A.HORAREGVIG, A.HORAENT, A.HORASAL, A.CHOFER, A.DESTINO, A.ANDEN, A.TRANSPORTE, A.NO_TRAILER, A.PLACA, A.PESOBASCULA, A.PESO, A.PDN_FOLIO FROM TB_MSTR_TRAILER A INNER JOIN tb_mstr_pedidos_nal B ON A.pdn_folio = B.pdn_folio WHERE A.fecha BETWEEN '" + mfec + "' AND '" + mfecF + "' AND B.pdn_fecha BETWEEN '" + mfec + "' AND '" + mfecF + "' AND A.conse > 0 ORDER BY a.fecha, a.conse";
            else if (Tipo == "CAMIONETAS")
                Cadena = "SELECT A.FECHA, A.TURNO, A.RESPONSABLE, A.CHOFER, A.DESTINO, SUBSTRING(A.HORAINI,12,24) AS HORAINI, SUBSTRING(A.HORAFIN,12,24) AS HORAFIN, A.ANDEN, A.TRANSPORTE, A.NO_TRAILER, B.placas, A.PESOBASCULA, A.PDN_FOLIO, B.PESOBRUTO FROM TB_MSTR_TRAILER A INNER JOIN tb_cat_vehiculos B ON A.no_trailer = B.clave WHERE A.FECHA BETWEEN '" + mfec + "' AND '" + mfecF + "' AND A.CONSE = 0 ORDER BY A.FECHA, A.NO_TRAILER";
            //Cadena = "SELECT A.CONSE,A.FECHA,A.TURNO,B.PDN_TIPO,A.RESPONSABLE,A.HORAREGVIG,A.HORAENT,A.HORASAL,A.CHOFER,A.DESTINO,A.ANDEN,A.TRANSPORTE,A.NO_TRAILER,A.PLACA,A.PESOBASCULA,A.PDN_FOLIO FROM TB_MSTR_TRAILER A INNER JOIN tb_mstr_pedidos_nal B ON A.pdn_folio = B.pdn_folio WHERE A.fecha BETWEEN '" + mfec + "' AND '" + mfecF + "' AND B.pdn_fecha BETWEEN '" + mfec + "' AND '" + mfecF + "' AND A.conse = 0 ORDER BY a.fecha, a.NO_TRAILER";
            //string Cadena = "SELECT FECHA,TURNO,RESPONSABLE,CHOFER,DESTINO,HORAINI,HORAFIN,ANDEN,TRANSPORTE,NO_TRAILER,LARGOTRA FROM TB_MSTR_TRAILER WHERE FECHA = '" + mfec + "'"; // AND CONSE > 0 ORDER BY FECHA,CONSE ";
            //MessageBox.Show(Cadena);
            SqlCommand cmd;
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion;
            SqlDataReader Info;
            Info = cmd.ExecuteReader();
            //MessageBox.Show("Termine Consultas!!!");
            DGBasc.Rows.Clear();
            while (Info.Read())
            {
                string mx = Info["NO_TRAILER"].ToString();
                int nPos = 1;
                decimal nPorEf = 0, nPosPen = 0;
                if (Tipo == "TRAILERS")
                {
                    nPos = PosiiconesXEmb(Info["FECHA"].ToString().Substring(0, 10), Info["NO_TRAILER"].ToString());
                    if (Convert.ToInt32(Info["PDN_FOLIO"]) > 300000) // Nacional
                    {
                        nPosPen = 28 - ((nPos > 28) ? 28 : nPos);
                        nPorEf = (nPos / Convert.ToDecimal(28));
                    }
                    else // de Exportacion
                    {
                        if (Convert.ToDecimal(Info["PESOBASCULA"]) > 0)
                        {
                            if (nPos > 0)
                            {
                                decimal mtar = nPos;
                                if (Convert.ToDecimal(Info["PESOBASCULA"]) < 20000)
                                    mtar = (20000 * nPos) / Convert.ToDecimal(Info["PESOBASCULA"]);
                                if (mtar > 28)
                                    nPosPen = 28 - nPos;
                                else
                                    nPosPen = mtar - ((nPos < 0) ? mtar : nPos);
                                nPorEf = nPos / (nPos + nPosPen);
                            }
                            else
                                nPorEf = 0;
                            //nPorEf = ((nPos) / mtar);
                        }
                    }
                }
                else if (Tipo == "CAMIONETAS")
                {
                    nPos = PosiiconesXEmb(Info["FECHA"].ToString().Substring(0, 10), Info["NO_TRAILER"].ToString().Trim());

                    pesoTotalEstimado = getPesoTotalCamioneta(Info["FECHA"].ToString().Substring(0, 10), Info["NO_TRAILER"].ToString().Trim());
                    //nPosPen = 28 - ((nPos > 28) ? 28 : nPos);
                    //nPorEf = (nPos / Convert.ToDecimal(28));

                    if (Convert.ToDecimal(Info["PESOBASCULA"]) > 0)
                    {
                        decimal mtar = nPos;
                        if (Convert.ToDecimal(Info["PESOBASCULA"]) <= Convert.ToDecimal(pesoTotalEstimado))
                            mtar = Convert.ToDecimal(Info["PESOBASCULA"]) / Convert.ToDecimal(Info["PESOBRUTO"]);
                        //if (mtar > 28)
                        //    nPosPen = 28 - nPos;
                        else
                            nPosPen = mtar - ((nPos < 0) ? mtar : nPos);
                        nPorEf = Convert.ToDecimal(Info["PESOBASCULA"]) / Convert.ToInt32(Info["PESOBRUTO"]);
                        //nPorEf = nPos / (nPos + nPosPen);
                        //nPorEf = ((nPos) / mtar);
                    }
                }
                if (Tipo == "TRAILERS")
                {
                    DGBasc.Rows.Add(Info["CONSE"].ToString().Trim(), Info["FECHA"].ToString().Substring(0, 10).Trim(), Info["TURNO"].ToString().Trim(), Info["PDN_TIPO"].ToString().Trim(), Info["HORAREGVIG"].ToString().Trim(), Info["HORAENT"].ToString().Trim(), Info["HORASAL"].ToString().Trim(),
                         Info["CHOFER"].ToString().Trim(), Info["DESTINO"].ToString().Trim(), Info["TRANSPORTE"].ToString().Trim(), Info["NO_TRAILER"].ToString().Trim(), Convert.ToDecimal(Info["PESOBASCULA"]).ToString("##,###.##"), Convert.ToDecimal(Info["PESO"]).ToString("##,###.##"), Info["NO_TRAILER"].ToString().Trim(), nPos, nPosPen, nPorEf);
                    //DGBasc.Rows.Add(Info["CONSE"].ToString(), Info["TURNO"].ToString().Substring(0, 10), Info["RESPONSABLE"].ToString(), Info["PDN_TIPO"].ToString(), Info["HORAREGVIG"].ToString(), Info["HORAENT"].ToString(), Info["HORASAL"].ToString(),
                    //     Info["CHOFER"].ToString(), Info["DESTINO"].ToString(), Info["TRANSPORTE"].ToString(), Info["NO_TRAILER"].ToString(), Convert.ToDecimal(Info["PESOBASCULA"]).ToString("##,###.##"), Info["NO_TRAILER"].ToString(), nPos, nPosPen, nPorEf);
                }
                else
                {

                    DGBasc.Rows.Add(Info["FECHA"].ToString().Substring(0, 10), Info["TURNO"].ToString().Trim(), Info["RESPONSABLE"].ToString().Trim(), Info["CHOFER"].ToString().Trim(), Info["DESTINO"].ToString().Trim(), Info["HORAINI"].ToString(), Info["HORAFIN"].ToString(), Info["ANDEN"].ToString().Trim(), Info["TRANSPORTE"].ToString().Trim(), Info["NO_TRAILER"].ToString().Trim(), Info["PLACAS"].ToString().Trim(), Convert.ToDecimal(Info["PESOBASCULA"]).ToString("##,###.##"), Info["NO_TRAILER"].ToString(), nPos, nPosPen, Convert.ToDouble(nPorEf));
                    //DGBasc.Rows.Add(Info["Conse"].ToString(), Info["Fecha"].ToString().Substring(0, 10), Info["Turno"].ToString(), Info["HoraRegVig"].ToString(), Info["HoraEnt"].ToString(), Info["HoraSal"].ToString(),
                    //     Info["Chofer"].ToString(), Info["Destino"].ToString(), Info["Transporte"].ToString(), Info["NO_TRAILER"].ToString(), Convert.ToDecimal(Info["PESOBASCULA"]).ToString("##,###.##"), Info["NO_TRAILER"].ToString(), nPos, nPosPen, nPorEf);
                }

            }
            thisConnecion.Close();
            FormatoBas(Tipo);
        }

        private int PosiiconesXEmb(string mFe, string NoTra)
        {
            int NumPos = 0;
            string Cadena = "SELECT A.SECCION FROM TB_DET_EMBARQUE A, TB_MSTR_EMBARQUE B, TB_CAT_PRODUCTO C " +
                            "WHERE SUBSTRING(B.HORA_TRAILER,1,10) = '" + mFe + "' AND B.NO_TRAILER = '" + NoTra + "' " +
                            "AND B.EMB_FOLIO = A.EMB_FOLIO AND A.PROD_CLAVE = C.PROD_CLAVE AND A.ESTATUS != 'C' ORDER BY A.SECCION,C.PROD_NOMBRE ";
            SqlDataAdapter da = new SqlDataAdapter(Cadena, thisConnecion);
            DataTable Det = new DataTable();
            da.Fill(Det);
            int pos = 0;
            foreach (DataRow row in Det.Rows)
            {
                if (Convert.ToInt32(row["Seccion"]) > pos)
                {
                    pos = Convert.ToInt32(row["Seccion"]);
                    NumPos++;
                }
            }
            return NumPos;
        }

        private void LLenaCamioneta()
        {
            int pesoTotalCamioneta = 0;
            PedidosdeldiaCam(DtCam.Value.ToShortDateString());
            thisConnecion.Open();
            string Cadena = "SELECT NO_TRAILER,RESPONSABLE,HORAINI,HORAFIN,ANDEN,PESO,PesoBascula  FROM TB_MSTR_TRAILER WHERE FECHA = '" + DtCam.Value.ToShortDateString() + "' AND CONSE = 0 ORDER BY FECHA,CONSE ";
            DataSet ds = new DataSet();
            SqlDataAdapter da = new SqlDataAdapter(Cadena, thisConnecion);
            da.Fill(ds, "Info");
            DataTable TiemposCam = ds.Tables["INFO"];
            thisConnecion.Close();
            DGCami.Rows.Clear();
            string CveCam = "";
            int i = 0;
            foreach (DataRow row in PedidosCamioneta.Rows)
            {
                if (CveCam != row["cve_auto"].ToString().Trim())
                {
                    CveCam = row["cve_auto"].ToString().Trim();
                    string Mped = row["pdn_folio"].ToString().Trim();
                    string ChoCam = "", Placa = "";
                    foreach (DataRow Row in CatVehi.Select("Clave = '" + row["cve_auto"].ToString().Trim() + "'"))
                    {
                        ChoCam = Row["Chofer"].ToString().Trim();
                        Placa = Row["placas"].ToString().Trim();
                    }
                    string mHi = "", mHf = "", Peso = "0", PesoB = "0";
                    Peso = GetPesoEstimadoCamionetas(DtCam.Value.ToShortDateString(), row["cve_auto"].ToString().Trim());
                    foreach (DataRow Row in TiemposCam.Select("NO_TRAILER = '" + CveCam + "'")) //Placa
                    {
                        mHi = Row["HORAINI"].ToString().Trim().Substring(10, Row["HORAINI"].ToString().Trim().Length - 10);
                        mHf = (Row["HORAFIN"].ToString().Trim() == "--:--") ? "--:--" : Row["HORAFIN"].ToString().Trim().Substring(10, Row["HORAFIN"].ToString().Trim().Length - 10);
                        //Peso = Row["Peso"].ToString();
                        Peso = GetPesoEstimadoCamionetas(DtCam.Value.ToShortDateString(), row["cve_auto"].ToString().Trim());
                        PesoB = Row["PesoBascula"].ToString();
                    }
                    //pesoTotalCamioneta=getPesoTotalCamioneta(DtCam.Value.ToShortDateString(), CveCam);
                    DGCami.Rows.Add(DtCam.Value.ToShortDateString(), Placa, CveCam, ChoCam, Mped, mHi, mHf, 0, 0, 0, Peso, PesoB);
                    DGCami.Rows[i].Cells["PEDIDOSCAM"].ToolTipText = "Doble Clic para ver las ordenes de Venta";
                    DGCami.Rows[i].Cells["CVEAUTO"].ToolTipText = "Doble Clic para ver la Relacion de las ordenes de Venta";

                    i++;
                }

            }
            i = 0;
            foreach (DataGridViewRow row in DGCami.Rows)
            {
                string mCan = "", mSur = "";
                DGCami.Rows[i].Cells["AvanceCam"].Value = PorceAvanceCamioneta(DGCami.Rows[i].Cells["Cveauto"].Value.ToString(), ref mCan, ref mSur);
                DGCami.Rows[i].Cells["CANTCAM"].Value = Convert.ToDecimal(mCan).ToString("#,##0");
                DGCami.Rows[i].Cells["CAMISUR"].Value = Convert.ToDecimal(mSur).ToString("#,##0");
                i++;
            }

        }

        private string GetPesoEstimadoCamionetas(string pdn_fecha, string cve_auto)
        {
            if (thisConnecion.State == ConnectionState.Closed) { thisConnecion.Open(); }
            string strPeso = "WITH EmbFolios AS (SELECT A.PDN_FOLIO FROM TB_MSTR_PEDIDOS_NAL A INNER JOIN TB_MSTR_FACTURAS_NAL B ON A.PDN_FOLIO = B.PDN_FOLIO WHERE A.PDN_FECHA = '" + pdn_fecha + "' AND B.CVE_AUTO = '" + cve_auto + "' AND A.pdn_estatus <> 'C'), PesosCalculados AS (SELECT SUM(pesochielo) AS TotalPesoChielo, SUM(peso) AS TotalPeso FROM tb_det_embarque WHERE emb_folio IN (SELECT PDN_FOLIO FROM EmbFolios)) SELECT CASE WHEN TotalPesoChielo > TotalPeso THEN TotalPesoChielo ELSE TotalPeso END AS Peso FROM PesosCalculados;";
            SqlCommand cmdPeso;
            cmdPeso = new SqlCommand(strPeso);
            cmdPeso.Connection = thisConnecion; //DBGAB
            string Peso = Convert.ToString(cmdPeso.ExecuteScalar());
            if (thisConnecion.State == ConnectionState.Open) { thisConnecion.Close(); }
            return Peso;
        }

