        private void FormatoEmb()
        {
            decimal EmbA = 0, EmbD = 0, EmbR = 0, EmbT = 0, EmbAA = 0, EmbDD = 0, EmbRR = 0, EmbTT = 0;
            for (int i = 0; i < DGTmpEmp.Rows.Count; i++)
            {
                //if (Datos.Rows[i]["Tipo"].ToString() != "0")
                //    DGPedidos.Rows[i].DefaultCellStyle.Font = new Font(DGPedidos.DefaultCellStyle.Font, FontStyle.Bold);
                //if (Datos.Rows[i]["Tipo"].ToString() == "1")
                //    DGPedidos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.Yellow;
                //if (Reporte.Rows[i]["Tipo"].ToString() == "2")
                //  DGDatos.Rows[i].DefaultCellStyle.BackColor = System.Drawing.Color.LightBlue;
                int Hora = (DGTmpEmp.Rows[i].Cells["TmpCar"].Value.ToString().Trim().Length > 4) ? Convert.ToInt32(DGTmpEmp.Rows[i].Cells["TmpCar"].Value.ToString().Substring(0, 2)) : -1;
                int Hora2 = (Convert.ToInt32(DGTmpEmp.Rows[i].Cells["HrSal"].Value.ToString().Substring(0, 2)) > 0) ? Convert.ToInt32(DGTmpEmp.Rows[i].Cells["TmpTot"].Value.ToString().Substring(0, 2)) : -1;
                decimal Hr3 = 0;
                int HrSal = 0;
                int MiSal = 0;
                decimal TSal = 0, TEnt = 0;

                if (DGTmpEmp.Rows[i].Cells["HrSal"].Value.ToString().Trim() != "00:00")
                {
                    HrSal = Convert.ToInt32(Convert.ToInt32(DGTmpEmp.Rows[i].Cells["HrSal"].Value.ToString().Substring(0, 2)));
                    MiSal = Convert.ToInt32(Convert.ToInt32(DGTmpEmp.Rows[i].Cells["HrSal"].Value.ToString().Substring(3, 2)));
                }
                else
                {
                    HrSal = System.DateTime.Now.Hour;
                    MiSal = System.DateTime.Now.Minute;
                }
                int HrReg = Convert.ToInt32(Convert.ToInt32(DGTmpEmp.Rows[i].Cells["HRLLEGO"].Value.ToString().Substring(0, 2)));
                int MiReg = Convert.ToInt32(Convert.ToInt32(DGTmpEmp.Rows[i].Cells["HRLLEGO"].Value.ToString().Substring(3, 2)));
                TEnt = (HrReg * 60) + MiReg;
                TSal = (HrSal * 60) + MiSal;
                if (DGTmpEmp.Rows[i].Cells["HrSal"].Value.ToString().Trim() != "00:00")
                    Hr3 = (TSal - TEnt) / 60;//HrSal - HrReg;
                else
                {
                    Hr3 = (TSal - TEnt) / 60;   //(DGTmpEmp.Rows[i].Cells["TmpTot"].Value.ToString().Trim().Length > 4) ? Convert.ToInt32(DGTmpEmp.Rows[i].Cells["TmpTot"].Value.ToString().Substring(0, 2)) : -1;
                    //MiSal = System.DateTime.Now.Minute; 
                }
                if (TSal < TEnt)
                {
                    TSal = ((HrSal + 24) * 60) + MiSal;
                    Hr3 = (TSal - TEnt) / 60;
                }
                //    Hr3 = Hr3 - 1;
                //else
                //    Hr3 = Hr3 + 1;
                string StaSur = DGTmpEmp.Rows[i].Cells["SURTIBLE"].Value.ToString();
                //string Hora = DGTmpEmp.Rows[i].Cells["TmpCar"].ToString();
                if (Hora > 2)
                {
                    DGTmpEmp.Rows[i].Cells["DestinoEmb"].Style.BackColor = System.Drawing.Color.Red;
                    DGTmpEmp.Rows[i].Cells["TmpCar"].Style.BackColor = System.Drawing.Color.Red;
                    DGTmpEmp.Rows[i].Cells["Transporte"].Style.BackColor = System.Drawing.Color.Red;
                    DGTmpEmp.Rows[i].Cells["TrailerEmb"].Style.BackColor = System.Drawing.Color.Red;
                    EmbR++;
                    EmbT++;
                }
                if (Hora >= 0 && Hora < 2)
                {
                    DGTmpEmp.Rows[i].Cells["DestinoEmb"].Style.BackColor = System.Drawing.Color.Green;
                    DGTmpEmp.Rows[i].Cells["TmpCar"].Style.BackColor = System.Drawing.Color.Green;
                    DGTmpEmp.Rows[i].Cells["Transporte"].Style.BackColor = System.Drawing.Color.Green;
                    DGTmpEmp.Rows[i].Cells["TrailerEmb"].Style.BackColor = System.Drawing.Color.Green;
                    EmbA++;
                    EmbT++;
                }
                if (Hora == 2)
                {
                    DGTmpEmp.Rows[i].Cells["DestinoEmb"].Style.BackColor = System.Drawing.Color.Yellow;
                    DGTmpEmp.Rows[i].Cells["TmpCar"].Style.BackColor = System.Drawing.Color.Yellow;
                    DGTmpEmp.Rows[i].Cells["Transporte"].Style.BackColor = System.Drawing.Color.Yellow;
                    DGTmpEmp.Rows[i].Cells["TrailerEmb"].Style.BackColor = System.Drawing.Color.Yellow;
                    EmbD++;
                    EmbT++;
                }
                if (Hr3 < 2)
                    DGTmpEmp.Rows[i].Cells["HRLLEGO"].Style.BackColor = System.Drawing.Color.Green;
                else if (Hr3 >= 2 && Hr3 < 4)
                    DGTmpEmp.Rows[i].Cells["HRLLEGO"].Style.BackColor = System.Drawing.Color.Yellow;
                else if (Hr3 >= 4 && Hr3 < 6)
                    DGTmpEmp.Rows[i].Cells["HRLLEGO"].Style.BackColor = System.Drawing.Color.Orange;
                else
                    DGTmpEmp.Rows[i].Cells["HRLLEGO"].Style.BackColor = System.Drawing.Color.Red;
                string TmpTot = Math.Truncate(Hr3).ToString("00") + ":" + ((Hr3 - Math.Truncate(Hr3)) * 60).ToString("00");
                DGTmpEmp.Rows[i].Cells["HRLLEGO"].ToolTipText = TmpTot;  //Hr3.ToString();
                if (Hora2 > 0)
                {
                    EmbTT++;
                    if (Hora2 > 2)
                        EmbRR++;
                    else
                        if (Hora2 >= 0 && Hora2 < 2)
                        EmbAA++;
                    else if (Hora2 == 2)
                        EmbDD++;
                }
                if (StaSur == "T")
                    DGTmpEmp.Rows[i].Cells["SURTIBLE"].Style.BackColor = System.Drawing.Color.Yellow;
                else
                    if (StaSur == "P" || StaSur == "A")
                {
                    DGTmpEmp.Rows[i].Cells["SURTIBLE"].Style.BackColor = System.Drawing.Color.Red;
                    DGTmpEmp.Rows[i].Cells["SURTIBLE"].Style.ForeColor = System.Drawing.Color.Yellow;
                }
                else if (StaSur == "S")
                    DGTmpEmp.Rows[i].Cells["SURTIBLE"].Style.BackColor = System.Drawing.Color.Green;
                if (DGTmpEmp.Rows[i].Cells["SURTIBLE"].Value.ToString() == "P")
                    DGTmpEmp.Rows[i].Cells["SURTIBLE"].ToolTipText = "Doble Clic para ver el detalle del Pedido de los Productos Pendientes";
                if (DGTmpEmp.Rows[i].Cells["SURTIBLE"].Value.ToString() == "S")
                    DGTmpEmp.Rows[i].Cells["SURTIBLE"].ToolTipText = "Doble Clic para ver el detalle del Pedido";
                if (DGTmpEmp.Rows[i].Cells["SURTIBLE"].Value.ToString() == "C")
                    DGTmpEmp.Rows[i].Cells["TrailerEmb"].ToolTipText = "Doble Clic para ver la Distribucion del Embarque";
                if (DGTmpEmp.Rows[i].Cells["HrEnt"].Value.ToString().Trim().Length > 0)
                    DGTmpEmp.Rows[i].Cells["TRANSPORTE"].ToolTipText = "Doble Clic para ver las Fotos del Trailer";
                if (DGTmpEmp.Rows[i].Cells["SURTIBLE"].Value.ToString() != "P" && DGTmpEmp.Rows[i].Cells["SURTIBLE"].Value.ToString() != "S" && DGTmpEmp.Rows[i].Cells["PEDIDOEMB"].Value.ToString().Trim().Length > 0)
                    DGTmpEmp.Rows[i].Cells["PEDIDOEMB"].ToolTipText = "Doble Clic para ver el Detalle de Pedido Vs Surtido";
            }
            TxtEmbA.Text = EmbA.ToString();
            TxtEmbD.Text = EmbD.ToString();
            TxtEmbR.Text = EmbR.ToString();
            if (EmbT > 0)
            {
                TxtEmbAPor.Text = ((EmbA / EmbT) * 100).ToString("###");
                TxtEmbDPor.Text = ((EmbD / EmbT) * 100).ToString("###");
                TxtEmbRPor.Text = ((EmbR / EmbT) * 100).ToString("###");
            }
            if (EmbTT > 0)
            {
                TxtEmbAAPor.Text = ((EmbAA / EmbTT) * 100).ToString("###");
                TxtEmbDDPor.Text = ((EmbDD / EmbTT) * 100).ToString("###");
                TxtEmbRRPor.Text = ((EmbRR / EmbTT) * 100).ToString("###");
            }
            TxtEmbAA.Text = EmbAA.ToString();
            TxtEmbDD.Text = EmbDD.ToString();
            TxtEmbRR.Text = EmbRR.ToString();
        }

