        private string PorceAvance(string Trailer)
        {
            string Info = "0";

            string Cadena = "SELECT SUM(pdn_num_unidades) AS CANTI FROM TB_MSTR_PEDIDOS_NAL A, tb_det_pedidos B WHERE A.pdn_folio = B.pdn_folio AND A.pdn_tipo = B.pdn_tipo AND PDN_FECHA = '" + System.DateTime.Now.ToShortDateString() + "' AND PLACACAJA = '" + Trailer + "' GROUP BY PLACACAJA" +
                           " UNION " +
                           "SELECT SUM(pdn_num_unidades) AS CANTI FROM TB_MSTR_PEDIDOS_EXP A, tb_det_pedidos B WHERE A.pdn_folio = B.pdn_folio AND A.pdn_tipo = B.pdn_tipo AND PDN_FECHA = '" + System.DateTime.Now.ToShortDateString() + "' AND PLACACAJA = '" + Trailer + "' GROUP BY PLACACAJA ";
            SqlCommand cmd;
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion; //DBGAB
            string Pedi = Convert.ToString(cmd.ExecuteScalar());
            Pedi = (Pedi.Trim().Length > 0) ? Pedi : "0";
            Cadena = "SELECT SUM(A.cajas) AS SURTI FROM tb_det_embarque A, tb_mstr_trailer B, tb_mstr_embarque C" +
                     " WHERE B.no_trailer = '" + Trailer + "' AND B.fecha = '" + System.DateTime.Now.ToShortDateString() + "' AND A.ESTATUS != 'C' AND B.hora_trailer = C.fecha_cap AND B.no_trailer = C.no_trailer AND C.emb_folio = A.emb_folio AND C.emb_tipo = A.emb_tipo GROUP BY C.no_trailer ";
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion; //DBGAB
            string Surti = Convert.ToString(cmd.ExecuteScalar());
            Surti = (Surti.Trim().Length > 0) ? Surti : "0";
            if (Convert.ToDecimal(Pedi) > 0)
                Info = ((Convert.ToDecimal(Surti) / Convert.ToDecimal(Pedi)) * 100).ToString("##0");
            return Info;
        }

        private string PorceAvanceCamioneta(string Cveauto, ref string CANT, ref string SUR)
        {
            string Info = "0";
            thisConnecion.Open();
            string Cadena = "SELECT SUM(pdn_num_unidades) AS CANTI FROM TB_MSTR_PEDIDOS_NAL A, tb_det_pedidos B, TB_MSTR_FACTURAS_NAL C WHERE A.pdn_folio = B.pdn_folio AND A.pdn_tipo = B.pdn_tipo AND PDN_FECHA = '" +
                             DtCam.Value.ToShortDateString() + "' AND C.CVE_AUTO = '" + Cveauto + "' AND A.PDN_ESTATUS <> 'C' AND C.PROV_CLAVE = 'MRLUCKY' AND C.PDN_FOLIO = A.PDN_FOLIO GROUP BY C.CVE_AUTO";
            SqlCommand cmd;
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion;
            string Pedi = Convert.ToString(cmd.ExecuteScalar());
            Pedi = (Pedi.Trim().Length > 0) ? Pedi : "0";
            Cadena = "SELECT SUM(A.cajas) AS SURTI FROM tb_det_embarque A, tb_mstr_facturas_nal B, tb_mstr_embarque C" +
                     " WHERE B.cve_auto = '" + Cveauto + "' AND B.fcn_fecha = '" + DtCam.Value.ToShortDateString() + "' AND A.ESTATUS != 'C' AND B.pdn_folio = C.EMB_FOLIO AND C.emb_folio = A.emb_folio AND C.emb_tipo = A.emb_tipo GROUP BY B.CVE_AUTO ";
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion;
            string Surti = Convert.ToString(cmd.ExecuteScalar());
            Surti = (Surti.Trim().Length > 0) ? Surti : "0";
            if (Convert.ToDecimal(Pedi) > 0)
                Info = ((Convert.ToDecimal(Surti) / Convert.ToDecimal(Pedi)) * 100).ToString("##0.00");
            thisConnecion.Close();
            CANT = Pedi;
            SUR = Surti;
            return Info;
        }

