        private void DGBasc_CellDoubleClick(object sender, DataGridViewCellEventArgs e)
        {
            if (LblTipoRevBas.Text == "TRAILERS")
            {
                if (DGBasc.CurrentCell.ColumnIndex == 0)
                {
                    Program.MyGlobal.PubFecEmb = DGBasc.CurrentRow.Cells["BASFECHA"].Value.ToString();
                    Program.MyGlobal.PubNoTrailer = DGBasc.CurrentRow.Cells["BASPLACA"].Value.ToString();
                    FrmCapPntRev Bascula = new FrmCapPntRev();
                    Bascula.ShowDialog(this);
                }
                if (DGBasc.CurrentCell.ColumnIndex == 11 || DGBasc.CurrentCell.ColumnIndex == 10 && DGBasc.CurrentRow.Cells["HoraSal"].Value.ToString() != "00:00")
                {
                    Program.MyGlobal.PubFecEmb = DGBasc.CurrentRow.Cells["BASFECHA"].Value.ToString();
                    Program.MyGlobal.PubNoTrailer = DGBasc.CurrentRow.Cells["BASPLACA"].Value.ToString();
                    FrmCapPesoBas Bascula = new FrmCapPesoBas();
                    Bascula.Tipo = "TRAILERS";
                    Bascula.ShowDialog(this);
                    LLenaBas(LblTipoRevBas.Text);
                }
            }
            else if (LblTipoRevBas.Text == "CAMIONETAS")
            {
                if (DGBasc.CurrentCell.ColumnIndex == 11 && DGBasc.CurrentRow.Cells["HoraSal"].Value.ToString() != "00:00")
                {
                    Program.MyGlobal.PubFecEmb = DGBasc.CurrentRow.Cells["BASCONSE"].Value.ToString();
                    Program.MyGlobal.PubNoTrailer = DGBasc.CurrentRow.Cells["BASTRANS"].Value.ToString();
                    FrmCapPesoBas Bascula = new FrmCapPesoBas();
                    Bascula.Tipo = "CAMIONETAS";
                    Bascula.ShowDialog(this);
                    LLenaBas(LblTipoRevBas.Text);
                }
            }
            else
            {

            }
        }

