            */


            string Cadena = "SELECT A.emb_folio, A.emb_tipo,  A.no_trailer, A.hora_trailer, A.emb_obs, B.prod_clave, SUM(B.cajas) AS CAJAS, C.Responsable,A.HORA_FIN  FROM tb_mstr_embarque A LEFT JOIN tb_det_embarque B ON A.emb_folio = B.emb_folio AND A.emb_tipo = B.emb_tipo AND B.ESTATUS != 'C' AND B.cajas > 0, tb_mstr_trailer C  WHERE A.fecha_cap >= '" + mfecI + "' and a.Fecha_cap <= '" + mfecF + "' AND C.GUARDAR = 'S'  AND A.NO_TRAILER = C.no_trailer AND A.HORA_TRAILER = C.HORA_TRAILER   GROUP BY A.emb_folio, A.emb_tipo,  A.no_trailer, A.hora_trailer, A.emb_obs, B.prod_clave, C.Responsable,A.HORA_FIN ORDER BY emb_folio";

