            Cadena = "SELECT A.pdn_folio, A.cnte_clave, A.pdn_tipo, B.prod_clave, B.pdn_num_unidades, C.FECHA_CAP, D.PROD_NOMBRE  " +
                     " FROM tb_mstr_pedidos_nal A, tb_det_pedidos B, tb_mstr_embarque C, TB_CAT_PRODUCTO D " +
                     " WHERE C.fecha_cap >= '" + mfecI + "' and C.Fecha_cap <= '" + mfecF + "' AND A.pdn_folio = C.emb_folio AND  A.pdn_folio = B.pdn_folio AND A.pdn_tipo = B.pdn_tipo AND B.PROD_CLAVE = D.PROD_CLAVE" +
                     " UNION " +
                     " SELECT A.pdn_folio, A.cnte_clave, A.pdn_tipo, B.prod_clave, B.pdn_num_unidades, C.FECHA_CAP, D.PROD_NOMBRE  " +
                     " FROM tb_mstr_pedidos_EXP A, tb_det_pedidos B, tb_mstr_embarque C, TB_CAT_PRODUCTO D  " +
                     " WHERE C.fecha_cap >= '" + mfecI + "' and C.Fecha_cap <= '" + mfecF + "' AND A.pdn_folio = C.emb_folio AND  A.pdn_folio = B.pdn_folio AND A.pdn_tipo = B.pdn_tipo AND B.PROD_CLAVE = D.PROD_CLAVE AND A.pdn_tipo = C.emb_tipo " +
                     " UNION " +
                     " SELECT A.EMB_folio AS PDN_FOLIO, A.cnte_clave, A.EMB_tipo AS PDN_TIPO, B.prod_clave, B.emb_unidades AS pdn_num_unidades, A.EMB_FECHA AS FECHA_CAP, D.PROD_NOMBRE  " +
                     " FROM tb_mstr_ordenes_emb A, tb_det_ordenes_emb B, TB_CAT_PRODUCTO D  " +
                     " WHERE A.EMB_fecha >= '" + mfecI + "' and A.EMB_Fecha <= '" + mfecF + "' AND A.emb_folio = B.emb_folio AND A.emb_SITUACION = B.emb_tipo and B.PROD_CLAVE = D.PROD_CLAVE ";
