            DataTable RepDetPed = new DataTable();
            RepDetPed = ds.Tables["INFO"];
            thisConnecion.Close();

            string mRES = "";
            string mPED1 = "";
            string mOBS = "";
            string Hora = "";
            int Mtot = 0;
            foreach (DataRow Row in RepDetPed.Rows)
            {

                string mPED = (Row["PDN_TIPO"].ToString() != "NAL") ? Row["PDN_FOLIO"].ToString().Trim().PadLeft(6, '0') : Row["PDN_FOLIO"].ToString();
                string mTIP = Row["PDN_TIPO"].ToString();
                if (mPED1 != mPED)
                {
                    mRES = "";
                    mOBS = "";
                    Hora = "";
                    foreach (DataRow row in RepDetEmb.Select("EMB_FOLIO = '" + mPED + "' AND EMB_TIPO = '" + mTIP + "'"))
                    {
                        mRES = row["RESPONSABLE"].ToString();
                        mOBS = row["EMB_OBS"].ToString();
                        Hora = row["HORA_FIN"].ToString();
                        break;
                    }
                    mPED1 = mPED;
                }
                if (mRES.Trim() == "")
                    continue;
                string mPROD = Row["PROD_CLAVE"].ToString();
                string mFEC = Convert.ToDateTime(Row["FECHA_CAP"]).ToString("MM/dd/yyyy");
                string mNOM = Row["PROD_NOMBRE"].ToString();


                decimal mCANT = Convert.ToDecimal(Row["PDN_NUM_UNIDADES"]), sur = 0;

                foreach (DataRow row in RepDetEmb.Select("prod_clave = '" + mPROD + "' AND EMB_FOLIO = '" + mPED + "' AND EMB_TIPO = '" + mTIP + "'"))
                    sur = sur + Convert.ToDecimal(row["CAJAS"]);
                if (mCANT != sur)
                {
                    string mCLI = Fn_TraeNomCli(Convert.ToString(Row["CNTE_CLAVE"].ToString()));
                    thisConnecion.Open();
                    string MFac = Fn_Factura(mPED, mTIP);
                    thisConnecion.Close();
                    if (mPED == "567201")
