            foreach (DataRow Row in RepDetEmb.Rows)
            {
                decimal sur = 0;
                try
                {
                    sur = Convert.ToDecimal(Row["CAJAS"]);
                }
                catch
                {

                }


                decimal mCANT = 0;
                string mFEC = "", mCLI = "", mNOM = "";
                string mPED = (Row["EMB_TIPO"].ToString() == "EXP") ? Convert.ToInt32(Row["EMB_FOLIO"]).ToString().Trim() : Row["EMB_FOLIO"].ToString();
                string mTIP = Row["EMB_TIPO"].ToString();
                string mPROD = Row["PROD_CLAVE"].ToString();
                Hora = Row["Hora_fin"].ToString();
                foreach (DataRow row in RepDetPed.Select("prod_clave = '" + mPROD + "' AND PDN_FOLIO = '" + mPED + "' AND PDN_TIPO = '" + mTIP + "'"))
                    mCANT = Convert.ToDecimal(row["PDN_NUM_UNIDADES"]);
                if (mCANT == 0)
                {
                    string Existe = "N";
                    foreach (DataRow row in RepDetPed.Select("PDN_FOLIO = '" + mPED + "' AND PDN_TIPO = '" + mTIP + "'"))
                    {
                        mFEC = Convert.ToDateTime(row["FECHA_CAP"]).ToString("MM/dd/yyyy");
                        mCLI = Fn_TraeNomCli(Convert.ToString(row["CNTE_CLAVE"].ToString()));
                        Existe = "S";
                    }

                    thisConnecion.Open();
                    string MFac = Fn_Factura(mPED, mTIP);
                    mNOM = Fn_TraeNomProd(mPROD);
