                                    hay = "S";
                                    DGResp.Rows[j].Cells["CantResp"].Value = Convert.ToInt32(DGResp.Rows[j].Cells["CantResp"].Value) + 1;
                                    break;
                                }
                                j++;
                            }
                            if (hay == "N")
                                DGResp.Rows.Add(mRES, 1, 0);
                        }
                    }

                }
            }
            int k = 0;
            foreach (DataGridViewRow row1 in DGResp.Rows)
            {
                decimal porce = Convert.ToDecimal(DGResp.Rows[k].Cells["CantResp"].Value) / Mtot;
                DGResp.Rows[k].Cells["PorceResp"].Value = porce * 100;
                k++;
            }
            FormatoRep();

            //DGRep.DataSource = RepDetPed;

