        private string Fn_TraeNomProd(string CveProd)
        {
            //thisConnecion.Open(); //DBGAB
            string Cadena = "SELECT PROD_NOMBRE FROM TB_CAT_PRODUCTO WHERE PROD_CLAVE = '" + CveProd + "'";
            SqlCommand cmd;
            cmd = new SqlCommand(Cadena);
            cmd.Connection = thisConnecion; //DBGAB
            string Info = Convert.ToString(cmd.ExecuteScalar());
            //thisConnecion.Close(); //DBGAB
            return Info;
        }

