        private void DGVPlacasLNP_CellContentDoubleClick(object sender, DataGridViewCellEventArgs e)
        {
            esAlta = false;
            modoRetirar = false;
            btnGuardar.Enabled = false;
            btnAgregarLNP.Enabled = true;
            btnRetirarLNP.Enabled = true;
            btnCancelar.Visible = false;

            if (DGVPlacasLNP.CurrentRow == null)
                return;

            DataGridViewRow fila = DGVPlacasLNP.CurrentRow;

            // Solo actualizar los TextBox si NO estamos en modo Alta ni en modo Retirar
            if (!esAlta && !modoRetirar)
            {
                txtBoxPlacaLNP.Text = fila.Cells["Placa"].Value.ToString().Trim();
                txtBoxMotivoLNP.Text = fila.Cells["Motivo"].Value.ToString().Trim();

                txtBoxPlacaLNP.ReadOnly = true;
                txtBoxMotivoLNP.ReadOnly = true;
            }
        }

        private void btnCancelar_Click(object sender, EventArgs e)
        {
            esAlta = false;
            modoRetirar = false;
            btnGuardar.Enabled = false;
            btnAgregarLNP.Enabled = true;
            btnRetirarLNP.Enabled = true;
            btnCancelar.Visible = false;
        }

        private string getPesoTotalCamioneta(string pdn_fecha, string cve_auto)
        {
            string pesoTotalCamioneta = "";
            string PESO = "";
            //connection with sql
            try
            {
                thisConnecion.Open();
                string Cadena = "EXECUTE getPesoEmbarqueCamioneta @pdn_fecha='" + pdn_fecha + "',@cve_auto='" + cve_auto + "'";
                SqlCommand cmd;
                cmd = new SqlCommand(Cadena, thisConnecion);
                SqlDataReader Info;
                Info = cmd.ExecuteReader();
                while (Info.Read())
                {
                    pesoTotalCamioneta = Info["PesoTotalCamioneta"].ToString();
                }
                thisConnecion.Close();

                //PESO = Convert.ToDecimal(pesoTotalCamioneta);
                return pesoTotalCamioneta;
            }
            catch (Exception e)
            {
                //PESO = Convert.ToDecimal(pesoTotalCamioneta);
                return pesoTotalCamioneta = "0";
            }
        }
    }
